export const adventures=[
 {id:'egg',icon:'🥚',name:'L’œuf perdu',reward:8,steps:[{x:-8,z:18,icon:'🐾',text:'Suis les premières empreintes'},{x:-18,z:24,icon:'🐾',text:'Une autre piste ! Continue'},{x:-25,z:17,icon:'🥚',text:'Retrouve le nid caché'},{x:0,z:13,icon:'⛺',text:'Rapporte l’œuf au camp'}]},
 {id:'treasure',icon:'💎',name:'Les trois indices',reward:12,steps:[{x:12,z:15,icon:'🔍',text:'Trouve le premier indice'},{x:23,z:8,icon:'🔍',text:'Trouve le deuxième indice'},{x:32,z:15,icon:'🔍',text:'Trouve le troisième indice'},{x:37,z:27,icon:'🎁',text:'Ouvre le coffre caché'}]},
 {id:'baby',icon:'🦕',name:'Le bébé égaré',reward:10,steps:[{x:-12,z:8,icon:'🦕',text:'Retrouve le bébé dinosaure'},{x:-20,z:1,icon:'🐾',text:'Accompagne le bébé vers sa famille'},{x:-27,z:-8,icon:'🦕',text:'Retrouve son troupeau'}]},
];
export function normalizeExpeditions(saved={}){const done=[...new Set((Array.isArray(saved?.done)?saved.done:[]).filter(id=>adventures.some(a=>a.id===id)))],a=adventures.find(a=>a.id===saved?.active?.id);return {done,active:a&&!done.includes(a.id)?{id:a.id,step:Math.max(0,Math.min(a.steps.length-1,Math.floor(Number(saved.active.step)||0)))}:null};}
export function startAdventure(state,id){if(state.active||state.done.includes(id)||!adventures.some(a=>a.id===id))return false;state.active={id,step:0};return true;}
export function advanceAdventure(state,inv,wardrobe){const a=adventures.find(a=>a.id===state.active?.id);if(!a||state.done.includes(a.id))return null;if(++state.active.step<a.steps.length)return {complete:false};state.done.push(a.id);state.active=null;inv.gems+=a.reward;const unlocked=state.done.length===adventures.length&&!wardrobe.owned.includes('explorer');if(unlocked)wardrobe.owned.push('explorer');return {complete:true,reward:a.reward,unlocked};}
